INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1084340-ise391', 'stk-user2352', 'ISE 391', 'info', '{"desc": "جودة المقرر بشكل عام\nكورس مفيد بشكل عام في تنمية مهارات الاتصال وحل المشاكل وادارة المشاريع\nوأنصح بتسجيله قبل السمر تريننق والكوأب\nالمواضيع التي يغطيها المقرر\nnine steps model\nوذلك عن طريق تصميم حلول هندسية باستخدام العلوم والبحوث\nالكتاب المستخدم للمقرر\nالكتاب صراحة كلام كثير وفلسفة زائدة\n\nالأسئلة والأمثلة المستخدمة في المقرر\nفيه هناك بروجكتين\ngroup project & individual project\nمدى فائدته في الناحية التطبيقية\nالكورس كله برزنتيشن وعرض خطوات الحلول حتى اختيار الحل الامثل\n\nللتذكير الكورس يتطلب انهاء ENGLISH214+ISE205", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-391-industrial-engineering-design/120944/2", "user": "user2352", "ts": 1346460879000, "tid": 120944, "pn": 2}}', 1346460879000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1450460-ise391', 'stk-fahad_2012', 'ISE 391', 'info', '{"desc": "الكورس بشكل مختصر يتكلم عن الخطوات اللازمة لتقديم منتج معين\nابتداءً من تجميع رغبات المستهلكين الى تصنيف الرغبات الى صناعة البدائل الى اختيار افضل خيار الى تقديم المنتج\nحالياً يدرس الكورس الدكتور نبيل نحاس والدكتور متمكن في الكورس\nبيكون مطلوب منك بروجكتين في الكورس وكلهم نفس الشيء في الخطوات\nاللهم واحد لحالك والثاني مع فريق مع بعض الاختلافات البسيطة جداً\n\nجودة المقرر بشكل عام : ممتاز\n\nالمواضيع التي يغطيها المقرر : Development processes , Product planning , Concept generation\n\nالكتاب المستخدم للمقرر : حشو كلام , السلايدات تكفي\n\nالأسئلة والأمثلة المستخدمة في المقرر : الاسئلة من نفس افكار السلايدات\n\nمدى فائدته في الناحية التطبيقية :\nالكورس عملي ولاحظت ان بعض الشركات في التدريب قد يكون عندها منتج معين\nوالكورس هذا ممكن يساعدك في انتاج المنتج\n\nالسيلبس", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-391-industrial-engineering-design/120944/3", "user": "Fahad_2012", "ts": 1464248312000, "tid": 120944, "pn": 3}}', 1464248312000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1524127-ise391', 'stk-feras-mtn', 'ISE 391', 'info', '{"desc": "Term 192\n\nجودة المقرر بشكل عام\nممتاز\n\nالمواضيع التي يغطيها المقرر\nالشباب اللي فوق ماقصرو في وصف وشرح ماسيتم اخذه في هذي المادة\n\nالكتاب المستخدم للمقرر\nالسلايدات تكفي\n\nإضافات\n(طبعا ماودي ازيد عن كلام الشباب اللي فوق الا الحاجات اللي ماتكلمو عنها + الحاجات اللي تم تحديثها )\n\n-من اسهل كورسات التخصص (مادة A+) واشوف بتستفيد منه كثير + بعضكم بيستمتع فيه … لكن متطلباته غثيثة كل اسبوع تقريبا بيكون فيه Assignment وبعضها متعبة واوقات تجلس عليها يوم خصوصا اللي فيها رسم للconcepts اللي سويتها … وعشان كذا انصح تخلصها اول باول عشان لا تنحشر مع مياجر المواد الثانية\n\n-مافيه ميدتيرم او مياجر … لكن بيكون فيه كويزات + فاينل + Team project فقط … الindividual project بيكون عبارة عن الAssignments اللي بيحطها كل اسبوع بس مابيطلبك في النهاية report فيه\n\n-الindividual project الدكتور بيختار لك المنتج … والTeam project المنتج بيكون من اختيار مجموعتكم\n\n-Team project هو نفس الخطوات اللي طبقتها في الindividual project بس اللهم المنتج غير وبيطلبك زود (Poster + Presentation + Report + Prototype )\n\nانا خذيت الكورس مع الدكتور اسماعيل المعراج وكان كويس … وفيه طلاب اخذوها مع احمد عطية وبرضو مدحوه في هذا الكورس\n\nوبالتوفيق للجميع", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-391-industrial-engineering-design/120944/4", "user": "Feras-MTN", "ts": 1595499582000, "tid": 120944, "pn": 4}}', 1595499582000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1527507-ise391', 'stk-guest', 'ISE 391', 'info', '{"desc": "Term 201 -online:\nالشباب ماقصرو وعطو تفاصيل المادة بشكل كافي.\nالمادة عبارة عن لاب ، الدكتور بيعطي برودكت لكل طالب من بداية الفصل وتجلس تشتغل عليه وتسوي عليه اسايمنتس وبنفس الوقت بيقسم مجموعات عشان المشروع الجماعي. ببساطة المشروع الفردي اغلبه بيكون الاسايمنت تشتغل عليه لين قريب نهاية الفصل وبرضو من ممكن ثالث اسبوع بتشتغل المشروع الجماعي الي هو برودكت من اختيار المجموعة بتسوو عليه نفس الي سويتوه فالمشروع الفردي لكن بزيادة كتابة ريبورت كامل وبرزنتيشن بوستر . المادة مافيها ميد تيرم ولا مياجر فقط كويزات وفاينل وطبعا اسايمنتس وشغل عالمشروع الجماعي. المادة يبغالها شغل اسبوعي تقريبا ويفضل انكم تبدأو اول ب اول عشان مايتراكم الشغل خاصة فالنهاية .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-391-industrial-engineering-design/120944/6", "user": "Guest", "ts": 1609627036000, "tid": 120944, "pn": 6}}', 1609627036000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2352-ise391', 'stk-user2352', 'ISE 391', 'doc', '{"docs": [{"id": "stk-dr-f98656", "n": "Dr. Mojahid F. Saeed Osman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ise391\nبنود التقييم :\n\nالتحضير : يحضر ويضع ما يقارب 10% على الحضور\nطريقة الشرح : سلايدات مختصرة\nالكويزات : ما اعطانا كوزات\nالمياجر: سهلة على شكل اختياري ومقالي ومسائل مباشرة\nالفاينلات : متوسط مائل للسهل الممتنع\nالقريد النهائي: يعطيك حقك 70 c و80b و 90a\nالصوت: واضح وهاديء\nإضافات : الدكتور متعاون وحبيب وطيب الاخلاق وأهم شيء تحضر وتحل الـhw وتسلم المطلوب في وقته\nخصوصا يعطي هوموركات طويلة نوعاً ما ولازم تكون مطبوعة بالكمبيوتر\nويكرف شوي في هذا الكورس ، لكن هو أفضل الموجودين بصفته جديد في القسم\n…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p774704-ise391", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mojahid-f-saeed-osman/98656/7", "user": "user2352", "ts": 1296026375000, "tid": 98656, "pn": 7}}]}', 1296026375000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2536-ise391', 'stk-user2536', 'ISE 391', 'doc', '{"docs": [{"id": "stk-dr-f98656", "n": "Dr. Mojahid F. Saeed Osman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE 391\n\nالتحضير : يحضر كل محاضرة وكل لاب واذا بتغيب ومعاك عذر خاص تكلمه ويمشيك بدون أي مشاكل حتى لو غبت وراسلته بعدين ما عندك مشكلة\n\nطريقة الشرح : الشرح متوسط … بس المادة اصلا ما تحتاج شرح …\n\nالكويزات : ما فيه\n\nالمياجر: سهلة جدا … تصم السلايدات وتجي تسمع … يحط قبل اي اختبار review sheet تذاكرها ويجي الاختبار منها فقط\n\nالفاينلات : نفس المياجر\n\nالقريد النهائي: A+++++++++++\n\nالصوت: واضح\n\nإضافات : هذا الشخص مكسب للجامعة … تعامل راقي … الدرجات ولا شيء عنده … الفايدة همه الأول والأخير … يساعد في الاختبارات لين تقولون امين … بصراحة فخر للجامعة تواجده والله يكثر من أمثاله 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p811507-ise391", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mojahid-f-saeed-osman/98656/14", "user": "user2536", "ts": 1299850839000, "tid": 98656, "pn": 14}}]}', 1299850839000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mkd-ise391', 'stk-mkd', 'ISE 391', 'doc', '{"docs": [{"id": "stk-dr-f172117", "n": "Dr. Mohamed Darghouth", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "نفس الكلام اللي قلته عن الدكتور في 402 يمشي عليه ب391، مع فروقات بسيطة\n\nبشكل عام لو أي دكتور ثاني منزلها أتوقع بيكون أفضل منه ب391 من ناحية قريدات ، المادة أغلبها سواليف وما تحتاج واحد شرّيح عشان تفهمها\n\nفي 181 كانت كومن درغوث وأحمد عطيّة وأنا ندمت إني ما نزلت مع عطية عشان أكون صريح ، المادة معه كانت أحسن بكثير من درغوث\n\nعلى كل حال تقييمي بيكون بشكل عام عن الاشياء اللي لاحظتها بدرغوث اللي فرقت ما بين تدريسه ب402 و تدريسه ب391\n\nالسمستر والمادة : ISE 391 - Term 181\nالتحضير : يوميا بداية الكلاس ـ زي العادة شديد بالتحضير\nطريقة الشرح : عادي ، 402 مادة مهمة وتحتاج تعرف كل شي فيها لكن 391 تحتاجها فقط كـ Background ما هو شي Critical بتخصصنا ISE\nالكويزات : حفظ صم من السلايدات ، الكويزات اللي بالزلط مهمة ولكن تحتاج تذاكر كويس بعدين تشقّر عليها\nالفاينلات : الفاينل Comprehensive كل شي معك ، عشان كذا حاول اذا بغيت تذاكر السلايدات للكويزات انك تسوي ملخصات شاملة بحيث انك تغطي كل شي واذا جا وقت الفاينل ما تنضغط لان كمية السلايدات اللي عليك مرعبة\nالصوت: واضح ، احيان يفصل اذا احد مسك جواله ولا قعد يضحك ويقعد يسفّل كأنه نظام ثانوي ، عامله بجد بتلقاه يحترمك واثقل ، يحترم الناس اللي ياخذون مواده بجدية ويعاملهم تعامل مختلف عن الباقين ، لكن لا زال إنسان مزاجي يوم يضحك يدخل مستانس ويوم فاصل ماله خلق يشوف أحد\nإضافات : زي ما ذكرت فوق ما انصح فيه ب391 مرة ، لو لقيت نحاس ولا عطية حاول تنزل معهم أفضل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1505531-ise391", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohamed-darghouth/172117/10", "user": "MKD", "ts": 1548930267000, "tid": 172117, "pn": 10}}]}', 1548930267000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bader_alqahtani-ise391', 'stk-bader_alqahtani', 'ISE 391', 'doc', '{"docs": [{"id": "stk-dr-f172117", "n": "Dr. Mohamed Darghouth", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE391-211\nالتحضير :\nيحضر في نهاية المحاضرة\nطريقة الشرح :\nيشرح السلايدات بوضوح بس صوته ما كان مرتفع ف حاول تجلس قدام عشان تقدر تسمعه\nالكويزات : يقولونا لا تذاكرون الا من الكتاب و فعلا ذاكرت اول كوزين من السلايدات و عيدت بعدها مسكت الكتاب و صرت اقدر احلها زين\n\nالفاينلات :الفاينال كان متوسط و جاب كيس ستدي الي كان يسوي الاسايمنت بنفسه و ما يزرفها بيكون وضعه حلو\nالقريد النهائي:A\nالصوت:منخفض لو كان فيه مكرفون كان بيكون شي جبار\nإضافات : يكره الجوال مرة لا تطلع جوالك عنده ولا بيفصل عليك و الدكتور طيب الصدق و محترم بس يوريك انه شديد عشان ما يفلونها الشباب\n…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533372-ise391", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohamed-darghouth/172117/13", "user": "Bader_Alqahtani", "ts": 1641682568000, "tid": 172117, "pn": 13}}]}', 1641682568000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
